import posthog, { PostHog } from 'posthog-js';
import SdkConfig from './SdkConfig';

interface IEvent {
    // The event name that will be used by PostHog.
    // TODO: standard format (camel case? snake? UpperCase?)
    eventName: string;

    // The properties of the event that will be stored in PostHog.
    properties: {};
}

export enum Anonymity {
    Anonymous,
    Pseudonymous
}

// If an event extends IPseudonymousEvent, the event contains pseudonymous data
// that won't be sent unless the user has explicitly consented to pseudonymous tracking.
// For example, hashed user IDs or room IDs.
export interface IPseudonymousEvent extends IEvent {}

// If an event extends IAnonymousEvent, the event strictly contains *only* anonymous data which
// may be sent without explicit user consent.
export interface IAnonymousEvent extends IEvent {}

export interface IRoomEvent extends IPseudonymousEvent {
    hashedRoomId: string | null;
}

export interface IOnboardingLoginBegin extends IAnonymousEvent {
    key: "onboarding_login_begin";
}

const hashHex = async (input: string): Promise<string> => {
    const buf = new TextEncoder().encode(input);
    const digestBuf = await window.crypto.subtle.digest("sha-256", buf);
    return [...new Uint8Array(digestBuf)].map((b: number) => b.toString(16).padStart(2, "0")).join("");
};

const knownScreens = new Set([
    "register", "login", "forgot_password", "soft_logout", "new", "settings", "welcome", "home", "start", "directory",
    "start_sso", "start_cas", "groups", "complete_security", "post_registration", "room", "user", "group",
]);

export async function getRedactedCurrentLocation(origin: string, hash: string, pathname: string, anonymity: Anonymity) {
    // Redact PII from the current location.
    // Anonymous mode redacts entirely; pseudonymous mode substitutes a hash.
    // For known screens, assumes a URL structure of /<screen name>/might/be/pii
    if (origin.startsWith('file://')) {
        pathname = "/<redacted_file_scheme_url>/";
    }

    let [_, screen, ...parts] = hash.split("/");

    if (!knownScreens.has(screen)) {
        screen = "<redacted_screen_name>";
    }

    for (let i = 0; i < parts.length; i++) {
        parts[i] = anonymity === Anonymity.Anonymous ? `<redacted>` : await hashHex(parts[i]);
    }

    const hashStr = `${_}/${screen}/${parts.join("/")}`;
    return origin + pathname + hashStr;
}

export class PosthogAnalytics {
    private anonymity = Anonymity.Anonymous;
    private initialised = false;
    private enabled = false;
    private posthog?: PostHog = null;
    private redactedCurrentLocation = null;

    private static _instance = null;

    public static instance(): PosthogAnalytics {
        if (!this._instance) {
            this._instance = new PosthogAnalytics(posthog);
        }
        return this._instance;
    }

    constructor(posthog: PostHog) {
        this.posthog = posthog;
    }

    public async init(anonymity: Anonymity | boolean = Anonymity.Anonymous) {
        this.initialised = false;
        this.enabled = false;
        this.setAnonymity(typeof anonymity === "boolean" ?
            (anonymity ? Anonymity.Anonymous : Anonymity.Pseudonymous) : anonymity);

        const posthogConfig = SdkConfig.get()["posthog"];
        if (typeof posthogConfig?.projectApiKey === "string" && posthogConfig.projectApiKey.trim() &&
            typeof posthogConfig?.apiHost === "string" && posthogConfig.apiHost.trim()) {
            // Update the redacted current location before initialising posthog, as posthog.init triggers
            // an immediate pageview event which calls the sanitize_properties callback
            await this.updateRedactedCurrentLocation();

            this.posthog.init(posthogConfig.projectApiKey, {
                api_host: posthogConfig.apiHost,
                autocapture: false,
                mask_all_text: true,
                mask_all_element_attributes: true,
                sanitize_properties: this.sanitizeProperties.bind(this),
            });
            this.initialised = true;
            this.enabled = true;
        }
    }

    private async updateRedactedCurrentLocation() {
        // TODO only calculate this when the location changes as its expensive
        const { origin, hash, pathname } = window.location;
        this.redactedCurrentLocation = await getRedactedCurrentLocation(
            origin, hash, pathname, this.anonymity);
    }

    private sanitizeProperties(properties: posthog.Properties, _: string): posthog.Properties {
        // Sanitize posthog's built in properties which leak PII e.g. url reporting
        // see utils.js _.info.properties in posthog-js

        // this.redactedCurrentLocation needs to have been updated prior to reaching this point as
        // updating it involves async, which this callback is not
        properties['$current_url'] = this.redactedCurrentLocation;

        if (this.anonymity === Anonymity.Anonymous) {
            // drop referrer information for anonymous users
            properties['$referrer'] = null;
            properties['$referring_domain'] = null;
            properties['$initial_referrer'] = null;
            properties['$initial_referring_domain'] = null;

            // drop device ID, which is a UUID persisted in local storage
            properties['$device_id'] = null;
        }

        return properties;
    }

    public async identifyUser(userId: string) {
        if (!this.enabled || this.anonymity !== Anonymity.Pseudonymous) return;
        if (!this.initialised) throw new Error("PostHog analytics is not initialised");
        const hashedUserId = await hashHex(userId);
        if (this.enabled && this.initialised && this.anonymity === Anonymity.Pseudonymous) {
            this.posthog.identify(hashedUserId);
        }
    }

    public isEnabled(): boolean {
        return this.enabled;
    }

    public isInitialised(): boolean {
        return this.initialised;
    }

    public setAnonymity(anonymity: Anonymity): void {
        this.anonymity = navigator.doNotTrack === "1" ? Anonymity.Anonymous : anonymity;
    }

    public getAnonymity(): Anonymity {
        return this.anonymity;
    }

    public setOnlyTrackAnonymousEvents(enabled: boolean) {
        this.setAnonymity(enabled ? Anonymity.Anonymous : Anonymity.Pseudonymous);
    }

    public logout(): void {
        if (this.enabled) this.posthog.reset();
        this.setAnonymity(Anonymity.Anonymous);
    }

    private async capture(eventName: string, properties: posthog.Properties, anonymity: Anonymity) {
        if (!this.enabled) return;
        if (!this.initialised) throw new Error("PostHog analytics is not initialised");
        if (anonymity === Anonymity.Pseudonymous && this.anonymity === Anonymity.Anonymous) return;
        await this.updateRedactedCurrentLocation();
        if (anonymity === Anonymity.Pseudonymous && this.anonymity === Anonymity.Anonymous) return;
        this.posthog.capture(eventName, properties);
    }

    public async trackPseudonymousEvent<E extends IPseudonymousEvent>(
        eventName: E["eventName"],
        properties: E["properties"],
    ) {
        await this.capture(eventName, properties, Anonymity.Pseudonymous);
    }

    public async trackAnonymousEvent<E extends IAnonymousEvent>(
        eventName: E["eventName"],
        properties: E["properties"],
    ) {
        await this.capture(eventName, properties, Anonymity.Anonymous);
    }

    public async trackRoomEvent<E extends IRoomEvent>(
        eventName: E["eventName"],
        roomId: string | null | undefined,
        properties: Omit<E["properties"], "roomId">,
    ) {
        if (!this.enabled) return;
        if (!this.initialised) throw new Error("PostHog analytics is not initialised");
        if (this.anonymity === Anonymity.Anonymous) return;
        const updatedProperties = {
            ...properties,
            hashedRoomId: roomId ? await hashHex(roomId) : null,
        };
        await this.capture(eventName, updatedProperties, Anonymity.Pseudonymous);
    }
}

export function getAnalytics(): PosthogAnalytics {
    return PosthogAnalytics.instance();
}
import { Anonymity, getRedactedCurrentLocation, IAnonymousEvent, IRoomEvent,
    PosthogAnalytics } from '../src/PosthogAnalytics';
import SdkConfig from '../src/SdkConfig';
import * as crypto from 'crypto';

class FakePosthog {
    public capture;
    public init;
    public identify;
    public reset;

    constructor() {
        this.capture = jest.fn();
        this.init = jest.fn();
        this.identify = jest.fn();
        this.reset = jest.fn();
    }
}

export interface ITestEvent extends IAnonymousEvent {
    key: "jest_test_event";
    properties: {
        foo: string;
    };
}

export interface ITestRoomEvent extends IRoomEvent {
    key: "jest_test_room_event";
    properties: {
        foo: string;
    };
}

describe("PosthogAnalytics", () => {
    let analytics: PosthogAnalytics;
    let fakePosthog: FakePosthog;

    beforeEach(() => {
        jest.spyOn(SdkConfig, "get").mockReturnValue({
            posthog: { projectApiKey: "foo", apiHost: "https://posthog.example" },
        });
        fakePosthog = new FakePosthog();
        analytics = new PosthogAnalytics(fakePosthog);
        window.crypto = {
            subtle: crypto.webcrypto.subtle,
        };
    });

    afterEach(() => {
        jest.restoreAllMocks();
        navigator.doNotTrack = null;
        window.crypto = null;
    });

    it("forces anonymous tracking under DNT while initializing", async () => {
        navigator.doNotTrack = "1";
        await analytics.init(Anonymity.Pseudonymous);
        expect(analytics.isInitialised()).toBe(true);
        expect(analytics.isEnabled()).toBe(true);
        expect(analytics.getAnonymity()).toBe(Anonymity.Anonymous);
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        await analytics.identifyUser("foo");
        expect(fakePosthog.capture).not.toHaveBeenCalled();
        expect(fakePosthog.identify).not.toHaveBeenCalled();
        analytics.setAnonymity(Anonymity.Pseudonymous);
        expect(analytics.getAnonymity()).toBe(Anonymity.Anonymous);
    });

    it.each([{}, { posthog: {} }, { posthog: { projectApiKey: "foo" } },
        { posthog: { projectApiKey: " ", apiHost: "host" } },
        { posthog: { projectApiKey: "foo", apiHost: "" } }])(
        "stays disabled for invalid config %#", async config => {
            jest.spyOn(SdkConfig, "get").mockReturnValue(config);
            await analytics.init(false);
            expect(analytics.isInitialised()).toBe(false);
            expect(analytics.isEnabled()).toBe(false);
            await expect(analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" }))
                .resolves.toBeUndefined();
            expect(fakePosthog.init).not.toHaveBeenCalled();
            expect(fakePosthog.capture).not.toHaveBeenCalled();
        });

    it("initialises with valid config and defaults to anonymous", async () => {
        expect(analytics.getAnonymity()).toBe(Anonymity.Anonymous);
        await analytics.init();
        expect(analytics.isInitialised()).toBe(true);
        expect(analytics.isEnabled()).toBe(true);
        expect(fakePosthog.init).toHaveBeenCalledTimes(1);
    });

    it("Should pass track() to posthog", async () => {
        await analytics.init(false);
        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls[0][0]).toBe("jest_test_event");
        expect(fakePosthog.capture.mock.calls[0][1]).toEqual({ foo: "bar" });
    });

    it("Should pass trackRoomEvent to posthog", async () => {
        await analytics.init(false);
        const roomId = "42";
        await analytics.trackRoomEvent<IRoomEvent>("jest_test_event", roomId, {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls[0][0]).toBe("jest_test_event");
        expect(fakePosthog.capture.mock.calls[0][1]).toEqual({
            foo: "bar",
            hashedRoomId: "73475cb40a568e8da8a045ced110137e159f890ac4da883b6b17dc651b3a8049",
        });
    });

    it("omits a room identifier when absent and suppresses room events in anonymous mode", async () => {
        await analytics.init(Anonymity.Pseudonymous);
        await analytics.trackRoomEvent<IRoomEvent>("jest_test_event", null, { foo: "bar" });
        expect(fakePosthog.capture).toHaveBeenCalledWith("jest_test_event", {
            foo: "bar", hashedRoomId: null,
        });
        analytics.setAnonymity(Anonymity.Anonymous);
        await analytics.trackRoomEvent<IRoomEvent>("jest_test_event", "42", { foo: "bar" });
        expect(fakePosthog.capture).toHaveBeenCalledTimes(1);
    });

    it("awaits URL redaction before capture and uses the current anonymity", async () => {
        window.location.hash = "#/register/some";
        await analytics.init(Anonymity.Pseudonymous);
        const sanitize = fakePosthog.init.mock.calls[0][1].sanitize_properties;
        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        const pseudonymousUrl = sanitize({})["$current_url"];
        analytics.setAnonymity(Anonymity.Anonymous);
        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" });
        const anonymousProperties = sanitize({});
        expect(anonymousProperties["$current_url"]).not.toBe(pseudonymousUrl);
        expect(anonymousProperties["$device_id"]).toBeNull();
        window.location.hash = "";
    });

    it("raises if capture is attempted while enabled but not initialised", async () => {
        await analytics.init(false);
        (analytics as any).initialised = false;
        await expect(analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", { foo: "bar" }))
            .rejects.toThrow("not initialised");
        expect(fakePosthog.capture).not.toHaveBeenCalled();
    });

    it("resets PostHog on logout and returns to anonymous mode", async () => {
        analytics.logout();
        expect(fakePosthog.reset).not.toHaveBeenCalled();
        await analytics.init(false);
        analytics.logout();
        expect(fakePosthog.reset).toHaveBeenCalledTimes(1);
        expect(analytics.getAnonymity()).toBe(Anonymity.Anonymous);
    });

    it("Should silently not track if not inititalised", async () => {
        await analytics.trackAnonymousEvent<ITestEvent>("jest_test_event", {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls.length).toBe(0);
    });

    it("Should not track non-anonymous messages if onlyTrackAnonymousEvents is true", async () => {
        await analytics.init(true);
        await analytics.trackPseudonymousEvent<ITestEvent>("jest_test_event", {
            foo: "bar",
        });
        expect(fakePosthog.capture.mock.calls.length).toBe(0);
    });

    it("Should identify the user to posthog if onlyTrackAnonymousEvents is false", async () => {
        await analytics.init(false);
        await analytics.identifyUser("foo");
        expect(fakePosthog.identify.mock.calls[0][0])
            .toBe("2c26b46b68ffc68ff99b453c1d30413413422d706483bfa0f98a5e886266e7ae");
    });

    it("Should not identify the user to posthog if onlyTrackAnonymousEvents is true", async () => {
        await analytics.init(true);
        await analytics.identifyUser("foo");
        expect(fakePosthog.identify.mock.calls.length).toBe(0);
    });

    it("Should pseudonymise a location of a known screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/register/some/pii", "/", Anonymity.Pseudonymous);
        expect(location).toBe(
            `https://foo.bar/#/register/\
a6b46dd0d1ae5e86cbc8f37e75ceeb6760230c1ca4ffbcb0c97b96dd7d9c464b/\
bd75b3e080945674c0351f75e0db33d1e90986fa07b318ea7edf776f5eef38d4`);
    });

    it("Should anonymise a location of a known screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/register/some/pii", "/", Anonymity.Anonymous);
        expect(location).toBe("https://foo.bar/#/register/<redacted>/<redacted>");
    });

    it("Should pseudonymise a location of an unknown screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/not_a_screen_name/some/pii", "/", Anonymity.Pseudonymous);
        expect(location).toBe(
            `https://foo.bar/#/<redacted_screen_name>/\
a6b46dd0d1ae5e86cbc8f37e75ceeb6760230c1ca4ffbcb0c97b96dd7d9c464b/\
bd75b3e080945674c0351f75e0db33d1e90986fa07b318ea7edf776f5eef38d4`);
    });

    it("Should anonymise a location of an unknown screen", async () => {
        const location = await getRedactedCurrentLocation(
            "https://foo.bar", "#/not_a_screen_name/some/pii", "/", Anonymity.Anonymous);
        expect(location).toBe("https://foo.bar/#/<redacted_screen_name>/<redacted>/<redacted>");
    });
});

